28	func doRequest(t *testing.T, method, url, body string) (int, map[string]any) {
29		t.Helper()
30		var reader *strings.Reader
31		if body != "" {
32			reader = strings.NewReader(body)
33		} else {
34			reader = strings.NewReader("")
35		}
36		request, err := http.NewRequest(method, url, reader)
