317	
318		cases := []string{
319			"?id=INC-1&severity=medium",   // id must be used alone
320			"?id=",                        // empty id
321			"?severity=",                  // empty severity
322			"?severity=urgent",            // unknown severity
323			"?stage=unknown",              // unknown stage
324			"?severity=low&severity=high", // repeated parameter
325			"?foo=bar",                    // unknown parameter
326		}
327		for _, query := range cases {
328			t.Run(query, func(t *testing.T) {
329				status, body := doRequest(t, http.MethodGet, server.URL+"/incidents"+query, "")
330				if status != http.StatusBadRequest {
331					t.Fatalf("status = %d, want 400", status)
332				}
333				if code := errorCode(t, body); code != "invalid_query" {
334					t.Fatalf("code = %q, want invalid_query", code)
335				}
336			})
337		}
